import { MakeLogicType, connect, kea, key, path, props, selectors } from 'kea'

import type { DataColorTheme } from 'lib/colors'
import { insightVizDataLogic } from 'scenes/insights/insightVizDataLogic'
import { keyForInsightLogicProps } from 'scenes/insights/sharedUtils'

import { InsightFilter, PathsV2Filter, PathsV2Results } from '~/queries/schema/schema-general'
import { InsightLogicProps } from '~/types'

import { JourneyGridModel, buildJourneyGridModel } from './journeyGridModel'

const DEFAULT_JOURNEYS_LOGIC_KEY = 'default_journeys_key'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface journeysDataLogicValues {
    insightData: Record<string, any> // insightVizDataLogic
    pathsV2Filter: PathsV2Filter | null | undefined // insightVizDataLogic
    theme: DataColorTheme | null // insightVizDataLogic
    gridModel: JourneyGridModel
    isAnchored: boolean
    results: PathsV2Results | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface journeysDataLogicActions {
    updateInsightFilter: (insightFilter: InsightFilter) => {
        insightFilter: InsightFilter
    } // insightVizDataLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface journeysDataLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        results: (insightData: Record<string, any>) => PathsV2Results | null
        isAnchored: (pathsV2Filter: PathsV2Filter | null | undefined) => boolean
        gridModel: (results: PathsV2Results | null) => JourneyGridModel
    }
}

export type journeysDataLogicType = MakeLogicType<
    journeysDataLogicValues,
    journeysDataLogicActions,
    InsightLogicProps,
    journeysDataLogicMeta
>

export const journeysDataLogic = kea<journeysDataLogicType>([
    props({} as InsightLogicProps),
    key(keyForInsightLogicProps(DEFAULT_JOURNEYS_LOGIC_KEY)),
    path((key) => ['products', 'product_analytics', 'insights', 'journeys', 'journeysDataLogic', key]),
    connect((props: InsightLogicProps) => ({
        values: [insightVizDataLogic(props), ['insightData', 'pathsV2Filter', 'theme']],
        actions: [insightVizDataLogic(props), ['updateInsightFilter']],
    })),
    selectors({
        results: [
            (s) => [s.insightData],
            (insightData: Record<string, any> | null): PathsV2Results | null => {
                const results = insightData?.result ?? insightData?.results
                return results && Array.isArray(results.steps) ? (results as PathsV2Results) : null
            },
        ],
        isAnchored: [
            (s) => [s.pathsV2Filter],
            (pathsV2Filter: PathsV2Filter | null): boolean => !!pathsV2Filter?.anchor,
        ],
        gridModel: [
            (s) => [s.results],
            (results: PathsV2Results | null): JourneyGridModel => buildJourneyGridModel(results),
        ],
    }),
])
